import React from 'react';
import { Helmet } from 'react-helmet';
import { Route, Routes, NavLink, useLocation } from 'react-router-dom';
import { LightTheme, BaseProvider } from 'baseui';
import { HeaderNavigation, ALIGN, StyledNavigationList, StyledNavigationItem } from 'baseui/header-navigation';
import { Button, KIND } from 'baseui/button';
import { SnackbarProvider, PLACEMENT } from 'baseui/snackbar';
import { Layer } from 'baseui/layer';
import Browser from './Routes/Browser';
import Collection from './Routes/Collection';
import Reader from './Routes/Reader';
import About from './Components/About';
import StandaloneWarning from './Components/StandaloneWarning';
import {
  READER_LAUNCH_START_EVENT,
  READER_READY_EVENT,
  cancelReaderLaunch,
  resetPwaChromeColor
} from './Components/PwaChrome';
import ReaderLaunchOverlay from './Components/ReaderLaunchOverlay';
import './App.css';

const App = (props) => {
  const [ackPwa, setAckPwa] = React.useState(localStorage.getItem('ack.pwa'));
  const [readerLaunchVisible, setReaderLaunchVisible] = React.useState(false);
  const drawer = React.useRef(null);
  const location = useLocation();
  const backgroundLocation = location.state?.backgroundLocation;
  const navigationLocation = backgroundLocation || location;

  const browseBase = `${process.env.PUBLIC_URL}/browse`;
  const collectionBase = `${process.env.PUBLIC_URL}/collection`;
  const pathname = navigationLocation.pathname;
  const browseActive = pathname === '/' ||
    pathname === `${process.env.PUBLIC_URL}` ||
    pathname === `${process.env.PUBLIC_URL}/` ||
    pathname.startsWith(browseBase);
  const collectionActive = pathname.startsWith(collectionBase);
  const getMenuButtonOverrides = (active) => ({
    Root: {
      style: {
        backgroundColor: active ? '#f6f6f688' : 'transparent',
        borderTopLeftRadius: '0',
        borderTopRightRadius: '0',
        borderBottomRightRadius: '0',
        borderBottomLeftRadius: '0',
        ':hover': {
          backgroundColor: active ? '#f6f6f688' : 'rgba(246, 246, 246, 0.32)'
        },
        ':active': {
          backgroundColor: active ? '#f6f6f688' : 'rgba(246, 246, 246, 0.48)'
        }
      }
    }
  });

  const isStandalone = () => {
    const matchMediaResult = typeof window.matchMedia === 'function'
      ? window.matchMedia('(display-mode: standalone)')
      : null;
    const standaloneMatch = Boolean(matchMediaResult && matchMediaResult.matches);

    return standaloneMatch || ackPwa;
  }

  const acknowledgeStandaloneWarning = () => {
    localStorage.setItem('ack.pwa', true);
    setAckPwa(true);
  }

  React.useEffect(() => {
    resetPwaChromeColor();
  }, []);

  React.useEffect(() => {
    const showReaderLaunchOverlay = () => setReaderLaunchVisible(true);
    const hideReaderLaunchOverlay = () => setReaderLaunchVisible(false);

    window.addEventListener(READER_LAUNCH_START_EVENT, showReaderLaunchOverlay);
    window.addEventListener(READER_READY_EVENT, hideReaderLaunchOverlay);

    return () => {
      window.removeEventListener(READER_LAUNCH_START_EVENT, showReaderLaunchOverlay);
      window.removeEventListener(READER_READY_EVENT, hideReaderLaunchOverlay);
    };
  }, []);

  return (
    <BaseProvider theme={LightTheme}>
      {!isStandalone()
        ?
        <StandaloneWarning onDismiss={() => acknowledgeStandaloneWarning()} />
        :
        <SnackbarProvider placement={PLACEMENT.top}>
          <Helmet>
            <title>LoboReader</title>
            <meta charSet="utf-8" />
            <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover"></meta>
            <meta name="robots" content="noindex" />
          </Helmet>
          <div className="pwaSafeAreaBackdrop" aria-hidden="true" />
          <About ref={drawer}></About>
          <Layer>
            <div className="anchored-top">
              <HeaderNavigation
                overrides={{
                  Root: {
                    style: {
                      height: '48px',
                    }
                  }
                }}>
                <StyledNavigationList>
                  <StyledNavigationItem className="header">
                    LoboReader
                  </StyledNavigationItem>
                </StyledNavigationList>
                <StyledNavigationList $align={ALIGN.center} />
                <StyledNavigationList $align={ALIGN.right}>
                  <StyledNavigationItem>
                    <div to="#">
                      <div
                        className="header"
                        style={{
                          float: 'right',
                          marginRight: '16px',
                          marginTop: '-4px',
                          fontSize: '75%'
                        }}
                        onClick={() => {
                          drawer.current.showDrawer();
                        }}
                      >
                        About
                      </div>
                    </div>
                  </StyledNavigationItem>
                </StyledNavigationList>
              </HeaderNavigation>
              <div className="menuBar">
                <div style={{ display: 'flex' }}>
                  <NavLink
                    to={browseBase}
                    className={browseActive ? 'menuActive' : undefined}>
                    <Button
                      kind={browseActive ? KIND.secondary : KIND.tertiary}
                      overrides={getMenuButtonOverrides(browseActive)}>Browse</Button>
                  </NavLink>
                  <NavLink
                    to={collectionBase}
                    className={collectionActive ? 'menuActive' : undefined}>
                    <Button
                      kind={collectionActive ? KIND.secondary : KIND.tertiary}
                      overrides={getMenuButtonOverrides(collectionActive)}>Collection</Button>
                  </NavLink>
                </div>
              </div>
            </div>
          </Layer>
          <div className="container">
            {/* With a reader open on top (backgroundLocation), this is the
                screen it was opened from; see .backgroundRoute in App.css. */}
            <div className={backgroundLocation ? 'backgroundRoute' : undefined}>
              <Routes location={backgroundLocation || location}>
                <Route path={`${process.env.PUBLIC_URL}/`} element={<Browser />} />
                <Route path={`${process.env.PUBLIC_URL}/browse/s/:searchQuery`} element={<Browser />} />
                <Route path={`${process.env.PUBLIC_URL}/browse/:id`} element={<Browser />} />
                <Route path={`${process.env.PUBLIC_URL}/browse`} element={<Browser />} />
                <Route path={`${process.env.PUBLIC_URL}/collection`} element={<Collection />} />
                <Route path={`${process.env.PUBLIC_URL}/read/:id`} element={<Reader />} />
                <Route path={`${process.env.PUBLIC_URL}/read/:id/p/:prevAction`} element={<Reader />} />
                <Route path={`${process.env.PUBLIC_URL}/read/:id/p/:prevAction/:prevId`} element={<Reader />} />
                <Route path="*" element={<Browser />} />
              </Routes>
            </div>
            {backgroundLocation && (
              <Routes>
                <Route path={`${process.env.PUBLIC_URL}/read/:id`} element={<Reader />} />
                <Route path={`${process.env.PUBLIC_URL}/read/:id/p/:prevAction`} element={<Reader />} />
                <Route path={`${process.env.PUBLIC_URL}/read/:id/p/:prevAction/:prevId`} element={<Reader />} />
              </Routes>
            )}
          </div>
          {readerLaunchVisible && (
            <ReaderLaunchOverlay
              onCancel={() => {
                // The reader (if it got as far as mounting) navigates back;
                // either way the overlay must go.
                cancelReaderLaunch();
                setReaderLaunchVisible(false);
              }}
            />
          )}
        </SnackbarProvider>
      }
    </BaseProvider>
  );
}

export default App
